package com.quickbite;
import javafx.application.Application;import javafx.geometry.*;import javafx.scene.*;import javafx.scene.control.*;import javafx.scene.layout.*;import javafx.stage.Stage;import javafx.collections.*;import java.sql.*;import java.util.*;import java.math.*;import java.nio.file.*;
public class App extends Application{
 Stage stage;BorderPane root=new BorderPane();int userId;String userName,role;Map<Integer,Integer> cart=new LinkedHashMap<>();List<Food> foods=new ArrayList<>();String category="All";String search="";Label cartCount=new Label();
 public void start(Stage s){stage=s;stage.setTitle("QuickBite • Campus Food Ordering");try{DB.init();login(false);}catch(Exception e){errorScreen(e);}stage.setMinWidth(950);stage.setMinHeight(680);stage.show();}
 void errorScreen(Exception e){VBox b=column(18);b.setAlignment(Pos.CENTER);b.getChildren().addAll(title("Database connection needed"),new Label("Start MySQL and configure QB_DB_USER / QB_DB_PASS."),new Label(e.getMessage()));stage.setScene(scene(b));}
 Scene scene(Parent p){Scene s=new Scene(p,1200,780);s.getStylesheets().add(Objects.requireNonNull(getClass().getResource("/com/quickbite/style.css")).toExternalForm());return s;}
 VBox column(double gap){VBox v=new VBox(gap);v.setPadding(new Insets(22));return v;} HBox row(double gap){HBox h=new HBox(gap);h.setAlignment(Pos.CENTER_LEFT);return h;}
 Label title(String s){Label l=new Label(s);l.getStyleClass().add("title");return l;}Label muted(String s){Label l=new Label(s);l.getStyleClass().add("muted");return l;} Button btn(String t,Runnable r){Button b=new Button(t);b.setOnAction(e->r.run());return b;}Button ghost(String t,Runnable r){Button b=btn(t,r);b.getStyleClass().add("ghost");return b;}
 void alert(String t){new Alert(Alert.AlertType.INFORMATION,t,ButtonType.OK).showAndWait();}void fail(Exception e){new Alert(Alert.AlertType.ERROR,e.getMessage(),ButtonType.OK).showAndWait();}
 void login(boolean signup){VBox form=column(16);form.setMaxWidth(440);form.getStyleClass().add("login-card");form.setAlignment(Pos.CENTER);Label logo=title("🍔 QuickBite");Label sub=muted("Your campus. Your cravings. Delivered to the counter.");TextField name=new TextField();name.setPromptText("Full name");TextField email=new TextField();email.setPromptText("College email");PasswordField pass=new PasswordField();pass.setPromptText("Password (minimum 6 characters)");form.getChildren().addAll(logo,sub);if(signup)form.getChildren().add(name);form.getChildren().addAll(email,pass,btn(signup?"Create account":"Login",()->{try{String em=email.getText().trim().toLowerCase(),pw=pass.getText();if(em.isBlank()||pw.isBlank())throw new Exception("Enter email and password.");if(signup){if(name.getText().isBlank()||pw.length()<6)throw new Exception("Enter name and a password of at least 6 characters.");try(Connection c=DB.connect();PreparedStatement q=c.prepareStatement("INSERT INTO users(name,email,password,role) VALUES(?,?,?,'STUDENT')")){q.setString(1,name.getText().trim());q.setString(2,em);q.setString(3,DB.hash(pw));q.executeUpdate();}alert("Account created! Please log in.");login(false);}else{try(Connection c=DB.connect();PreparedStatement q=c.prepareStatement("SELECT id,name,role FROM users WHERE email=? AND password=?")){q.setString(1,em);q.setString(2,DB.hash(pw));try(ResultSet rs=q.executeQuery()){if(!rs.next())throw new Exception("Incorrect email or password.");userId=rs.getInt(1);userName=rs.getString(2);role=rs.getString(3);cart.clear();home();}}}}catch(Exception ex){fail(ex);}}),ghost(signup?"Already have an account? Login":"New here? Create account",()->login(!signup)));
 StackPane bg=new StackPane(form);bg.getStyleClass().add("login-bg");stage.setScene(scene(bg));}
 void shell(String selected){root=new BorderPane();VBox sidebar=column(15);sidebar.setPrefWidth(210);sidebar.getStyleClass().add("sidebar");sidebar.getChildren().addAll(title("🍔 QuickBite"),muted("CAMPUS FOOD CLUB"),nav("🏠  Explore",()->home()),nav("🛒  My Cart",()->cartPage()),nav("🧾  My Orders",()->ordersPage()));if("ADMIN".equals(role))sidebar.getChildren().addAll(new Separator(),nav("📊  Admin Orders",()->adminOrders()),nav("📦  Inventory",()->inventory()));Region space=new Region();VBox.setVgrow(space,Priority.ALWAYS);sidebar.getChildren().addAll(space,muted("Signed in: "+userName),ghost("↪ Logout",()->{cart.clear();login(false);}));root.setLeft(sidebar);stage.setScene(scene(root));}
 Button nav(String t,Runnable r){Button b=ghost(t,r);b.setMaxWidth(Double.MAX_VALUE);b.getStyleClass().add("nav");return b;}
 void loadFoods()throws Exception{foods.clear();try(Connection c=DB.connect();PreparedStatement q=c.prepareStatement("SELECT id,name,category,price,stock,emoji,description FROM foods WHERE active=TRUE ORDER BY category,name");ResultSet rs=q.executeQuery()){while(rs.next())foods.add(Food.from(rs));}}
 void home(){try{loadFoods();}catch(Exception e){fail(e);return;}shell("home");VBox body=column(18);HBox top=row(15);VBox heads=new VBox(3,title("What are you craving? 😋"),muted("Fresh food, happy mood. Order ahead and skip the queue."));Region spacer=new Region();HBox.setHgrow(spacer,Priority.ALWAYS);top.getChildren().addAll(heads,spacer,btn("🛒 Cart ("+cart.values().stream().mapToInt(Integer::intValue).sum()+")",()->cartPage()));body.getChildren().add(top);
 VBox banner=column(7);banner.getStyleClass().add("hero");banner.getChildren().addAll(title("🔥 Campus cravings, sorted."),new Label("Burgers • Pizza • Momos • Chole Bhature • Shakes & more"),new Label("Order now • Pick up fresh • Pay your way"));body.getChildren().add(banner);
 TextField searchBox=new TextField(search);searchBox.setPromptText("🔎 Search dishes, categories, favorites...");searchBox.setOnAction(e->{search=searchBox.getText();home();});body.getChildren().add(searchBox);
 HBox categories=row(8);for(String c:List.of("All","Burgers","Pizza","North Indian","South Indian","Chinese","Snacks","Beverages","Desserts")){Button chip=ghost(c,()->{category=c;home();});if(category.equals(c))chip.getStyleClass().add("selected");categories.getChildren().add(chip);}ScrollPane catScroll=new ScrollPane(categories);catScroll.setFitToHeight(true);catScroll.setHbarPolicy(ScrollPane.ScrollBarPolicy.AS_NEEDED);catScroll.getStyleClass().add("transparent");body.getChildren().add(catScroll);
 FlowPane grid=new FlowPane(15,15);for(Food f:foods){if(!category.equals("All")&&!f.category().equals(category))continue;if(!((f.name()+" "+f.category()).toLowerCase().contains(search.toLowerCase())))continue;VBox card=column(7);card.getStyleClass().add("food-card");card.setPrefWidth(218);Label emoji=new Label(f.emoji());emoji.getStyleClass().add("food-emoji");Label name=new Label(f.name());name.getStyleClass().add("food-name");name.setWrapText(true);Label desc=muted(f.description());desc.setWrapText(true);Label price=new Label("₹"+f.price().toPlainString());price.getStyleClass().add("price");Button add=btn(f.stock()>0?"+ Add to cart":"Sold out",()->{cart.merge(f.id(),1,Integer::sum);home();});add.setDisable(f.stock()<=0);card.getChildren().addAll(emoji,name,desc,price,muted(f.stock()+" available"),add);grid.getChildren().add(card);}if(grid.getChildren().isEmpty())body.getChildren().add(muted("No matching dishes found."));else body.getChildren().add(grid);ScrollPane sc=new ScrollPane(body);sc.setFitToWidth(true);root.setCenter(sc);}
 Map<Integer,Food> foodMap(){Map<Integer,Food> m=new HashMap<>();for(Food f:foods)m.put(f.id(),f);return m;}
 BigDecimal total(){Map<Integer,Food> m=foodMap();BigDecimal t=BigDecimal.ZERO;for(var e:cart.entrySet())if(m.containsKey(e.getKey()))t=t.add(m.get(e.getKey()).price().multiply(BigDecimal.valueOf(e.getValue())));return t;}
 void cartPage(){try{loadFoods();}catch(Exception e){fail(e);return;}shell("cart");VBox v=column(16);v.getChildren().add(title("🛒 Your Cart"));if(cart.isEmpty()){v.getChildren().addAll(muted("Your cart is empty. Add something delicious!"),btn("Browse Menu",()->home()));root.setCenter(v);return;}Map<Integer,Food> m=foodMap();for(var e:new ArrayList<>(cart.entrySet())){Food f=m.get(e.getKey());if(f==null)continue;HBox item=row(16);item.getStyleClass().add("line-item");Label label=new Label(f.emoji()+"  "+f.name()+"   ₹"+f.price());Region sp=new Region();HBox.setHgrow(sp,Priority.ALWAYS);item.getChildren().addAll(label,sp,ghost("−",()->{cart.computeIfPresent(f.id(),(k,n)->n<=1?null:n-1);cartPage();}),new Label(""+e.getValue()),ghost("+",()->{if(cart.get(f.id())>=f.stock()){alert("Only "+f.stock()+" available");return;}cart.merge(f.id(),1,Integer::sum);cartPage();}),ghost("✕",()->{cart.remove(f.id());cartPage();}));v.getChildren().add(item);}v.getChildren().addAll(title("Total: ₹"+total().toPlainString()),muted("No extra fees • Counter pickup"),btn("Proceed to Checkout →",()->checkout()));root.setCenter(new ScrollPane(v));}
 void checkout(){shell("checkout");VBox v=column(18);v.setMaxWidth(650);v.getChildren().addAll(title("Secure Checkout 🔐"),muted("Choose how you'd like to pay."),title("Payable: ₹"+total().toPlainString()));ComboBox<String> payment=new ComboBox<>(FXCollections.observableArrayList("Cash on Pickup","UPI (Demo)","Card (Demo)"));payment.setValue("Cash on Pickup");payment.setMaxWidth(Double.MAX_VALUE);Label note=muted("UPI and Card are simulated demo payments. No money is transferred.");v.getChildren().addAll(payment,note,btn("Place Order • ₹"+total().toPlainString(),()->{try{if(cart.isEmpty())throw new Exception("Your cart is empty.");int id=DB.place(userId,cart,payment.getValue());cart.clear();alert("Order #"+id+" placed successfully!"+(payment.getValue().equals("Cash on Pickup")?" Pay at the counter.":" Demo payment successful."));receipt(id);}catch(Exception ex){fail(ex);}}));root.setCenter(v);}
 void ordersPage(){shell("orders");VBox v=column(14);v.getChildren().add(title("🧾 My Orders"));try(Connection c=DB.connect();PreparedStatement q=c.prepareStatement("SELECT id,created_at,status,payment_method,payment_status,total FROM orders WHERE user_id=? ORDER BY id DESC")){q.setInt(1,userId);try(ResultSet rs=q.executeQuery()){boolean any=false;while(rs.next()){any=true;int id=rs.getInt(1);HBox line=row(14);line.getStyleClass().add("line-item");VBox info=new VBox(4,new Label("Order #"+id+"  •  ₹"+rs.getBigDecimal(6)),muted(rs.getTimestamp(2)+"  •  "+rs.getString(4)+" / "+rs.getString(5)),new Label("Status: "+rs.getString(3)));Region sp=new Region();HBox.setHgrow(sp,Priority.ALWAYS);line.getChildren().addAll(info,sp,ghost("View Bill",()->receipt(id)));v.getChildren().add(line);}if(!any)v.getChildren().add(muted("No orders yet."));}}catch(Exception e){fail(e);}v.getChildren().add(btn("Refresh Status ↻",()->ordersPage()));root.setCenter(new ScrollPane(v));}
 void receipt(int id){shell("receipt");VBox v=column(11);v.setMaxWidth(650);StringBuilder bill=new StringBuilder("QUICKBITE • CAMPUS CANTEEN\nOrder #"+id+"\n");try(Connection c=DB.connect();PreparedStatement q=c.prepareStatement("SELECT o.id,o.created_at,o.status,o.payment_method,o.payment_status,o.total,u.name FROM orders o JOIN users u ON o.user_id=u.id WHERE o.id=? AND (o.user_id=? OR ?='ADMIN')")){q.setInt(1,id);q.setInt(2,userId);q.setString(3,role);try(ResultSet rs=q.executeQuery()){if(!rs.next())throw new Exception("Order not found.");v.getChildren().addAll(title("🧾 QuickBite Digital Bill"),muted("Order #"+id+"  •  "+rs.getTimestamp(2)),new Label("Customer: "+rs.getString(7)),new Label("Status: "+rs.getString(3)),new Label("Payment: "+rs.getString(4)+" ("+rs.getString(5)+")"));bill.append("Date: ").append(rs.getTimestamp(2)).append("\nCustomer: ").append(rs.getString(7)).append("\nStatus: ").append(rs.getString(3)).append("\nPayment: ").append(rs.getString(4)).append(" / ").append(rs.getString(5)).append("\n-----------------------\n");BigDecimal t=rs.getBigDecimal(6);try(PreparedStatement items=c.prepareStatement("SELECT food_name,qty,unit_price FROM order_items WHERE order_id=?")){items.setInt(1,id);try(ResultSet lines=items.executeQuery()){while(lines.next()){String line=lines.getString(1)+" × "+lines.getInt(2)+"   ₹"+lines.getBigDecimal(3).multiply(BigDecimal.valueOf(lines.getInt(2)));v.getChildren().add(new Label(line));bill.append(line).append("\n");}}}v.getChildren().add(title("Total ₹"+t));bill.append("-----------------------\nTOTAL ₹").append(t).append("\nThank you for ordering!");}v.getChildren().addAll(btn("Save Bill as .txt",()->{try{Path path=Path.of(System.getProperty("user.home"),"QuickBite-Bill-"+id+".txt");Files.writeString(path,bill.toString());alert("Bill saved: "+path);}catch(Exception e){fail(e);}}),ghost("Back to Orders",()->ordersPage()));}catch(Exception e){fail(e);}root.setCenter(new ScrollPane(v));}
 void adminOrders(){if(!"ADMIN".equals(role))return;shell("admin");VBox v=column(14);v.getChildren().add(title("📊 Admin • Manage Orders"));try(Connection c=DB.connect();Statement q=c.createStatement();ResultSet rs=q.executeQuery("SELECT o.id,u.name,o.total,o.status,o.payment_status,o.payment_method,o.created_at FROM orders o JOIN users u ON o.user_id=u.id ORDER BY o.id DESC LIMIT 200")){while(rs.next()){int id=rs.getInt(1);HBox line=row(12);line.getStyleClass().add("line-item");VBox info=new VBox(4,new Label("#"+id+" • "+rs.getString(2)+" • ₹"+rs.getBigDecimal(3)),muted(rs.getTimestamp(7)+" • "+rs.getString(6)+" • "+rs.getString(5)));ComboBox<String> status=new ComboBox<>(FXCollections.observableArrayList("PLACED","PREPARING","READY","COMPLETED","CANCELLED"));status.setValue(rs.getString(4));Button save=btn("Update",()->{try(Connection cn=DB.connect();PreparedStatement p=cn.prepareStatement("UPDATE orders SET status=?,payment_status=CASE WHEN ?='COMPLETED' AND payment_method='Cash on Pickup' THEN 'PAID' ELSE payment_status END WHERE id=?")){p.setString(1,status.getValue());p.setString(2,status.getValue());p.setInt(3,id);p.executeUpdate();adminOrders();}catch(Exception e){fail(e);}});line.getChildren().addAll(info,status,save,ghost("Bill",()->receipt(id)));v.getChildren().add(line);}}catch(Exception e){fail(e);}v.getChildren().add(btn("Refresh ↻",()->adminOrders()));root.setCenter(new ScrollPane(v));}
 void inventory(){if(!"ADMIN".equals(role))return;shell("inventory");VBox v=column(12);v.getChildren().addAll(title("📦 Inventory & Menu"),btn("+ Add New Dish",()->foodEditor(null)));try(Connection c=DB.connect();Statement s=c.createStatement();ResultSet rs=s.executeQuery("SELECT id,name,category,price,stock,emoji,description FROM foods WHERE active=TRUE ORDER BY category,name")){while(rs.next()){Food f=Food.from(rs);HBox line=row(12);line.getStyleClass().add("line-item");Label label=new Label(f.emoji()+" "+f.name()+"  •  "+f.category()+"  •  ₹"+f.price()+"  •  Stock: "+f.stock());Region sp=new Region();HBox.setHgrow(sp,Priority.ALWAYS);line.getChildren().addAll(label,sp,ghost("Edit",()->foodEditor(f)),ghost("Hide",()->{try(Connection cn=DB.connect();PreparedStatement q=cn.prepareStatement("UPDATE foods SET active=FALSE WHERE id=?")){q.setInt(1,f.id());q.executeUpdate();inventory();}catch(Exception e){fail(e);}}));v.getChildren().add(line);}}catch(Exception e){fail(e);}root.setCenter(new ScrollPane(v));}
 void foodEditor(Food f){Dialog<ButtonType> d=new Dialog<>();d.setTitle(f==null?"Add Dish":"Edit Dish");d.getDialogPane().getButtonTypes().addAll(ButtonType.OK,ButtonType.CANCEL);VBox form=new VBox(10);form.setPadding(new Insets(15));TextField name=new TextField(f==null?"":f.name()),cat=new TextField(f==null?"Snacks":f.category()),price=new TextField(f==null?"99":f.price().toString()),stock=new TextField(f==null?"20":""+f.stock()),emoji=new TextField(f==null?"🍽️":f.emoji()),desc=new TextField(f==null?"":f.description());for(var pair:List.of(new Object[]{"Dish name",name},new Object[]{"Category",cat},new Object[]{"Price (₹)",price},new Object[]{"Stock",stock},new Object[]{"Emoji",emoji},new Object[]{"Description",desc})){form.getChildren().addAll(new Label((String)pair[0]),(TextField)pair[1]);}d.getDialogPane().setContent(new ScrollPane(form));if(d.showAndWait().orElse(ButtonType.CANCEL)!=ButtonType.OK)return;try{BigDecimal amount=new BigDecimal(price.getText());int qty=Integer.parseInt(stock.getText());if(name.getText().isBlank()||cat.getText().isBlank()||amount.signum()<0||qty<0)throw new Exception("Check name, category, price and stock.");String sql=f==null?"INSERT INTO foods(name,category,price,stock,emoji,description) VALUES(?,?,?,?,?,?)":"UPDATE foods SET name=?,category=?,price=?,stock=?,emoji=?,description=? WHERE id=?";try(Connection c=DB.connect();PreparedStatement q=c.prepareStatement(sql)){q.setString(1,name.getText());q.setString(2,cat.getText());q.setBigDecimal(3,amount);q.setInt(4,qty);q.setString(5,emoji.getText());q.setString(6,desc.getText());if(f!=null)q.setInt(7,f.id());q.executeUpdate();}inventory();}catch(Exception e){fail(e);}}
 public static void main(String[]args){launch(args);}
}
